			    var grdList = e.control;
			    
			    if(!e.oldSelection[0]) return;
			    
			    var vsRowState = util.Grid.getRowState(app, "grdList", e.oldSelection[0]);
			    
			    // 변경되지 않은 상태(1), 행이 신규로 추가된 상태 (2) RowState 참고
			    if(vsRowState == 2){
			        
			        util.Msg.alert(app, "작성중인 개인상담 신청서가 있습니다.");
			        e.preventDefault();       
			    }    
